import Foundation

/// On-disk format of the bundled sample library (`sample_library.json`), generated by
/// `tools/content/build_sample_library.py`. Normalized: passages reference sections and translations by ID.
struct SampleLibraryDTO: Decodable, Sendable {
    /// v2: scripture only. v3 adds editorial themes (optional, so v2 packages still decode).
    static let supportedSchemaVersions = 2...3

    struct Source: Decodable, Sendable {
        let id: String
        let name: String
        let url: String?
        let license: String
        let attribution: String
    }

    struct Collection: Decodable, Sendable {
        let id: String
        let religionID: String
        let name: String
        let structureDescription: String
        let languages: [String]
        let availability: ScriptureCollection.Availability
        let originalLanguage: String
        let originalSourceID: String?
        let defaultTranslationID: String
    }

    struct TranslationDTO: Decodable, Sendable {
        let id: String
        let collectionID: String
        let name: String
        let languageCode: String
        let translator: String
        let year: Int?
        let sourceID: String
    }

    struct Book: Decodable, Sendable {
        let id: String
        let collectionID: String
        let title: String
        let division: String?
        let sequence: Int
    }

    struct Section: Decodable, Sendable {
        let id: String
        let bookID: String
        let title: String
        let sequence: Int
    }

    struct Passage: Decodable, Sendable {
        let id: String
        let sectionID: String
        let sequence: Int
        let reference: String
        let originalText: String?
        /// translationID -> text
        let texts: [String: String]
        /// Editorial theme IDs (schema v3).
        let themes: [String]?
    }

    /// An editorial label for what passages explicitly speak of. Not scripture.
    struct Theme: Decodable, Sendable {
        let id: String
        let name: String
    }

    let schemaVersion: Int
    let religions: [Religion]
    let sources: [Source]
    let collections: [Collection]
    let translations: [TranslationDTO]
    let books: [Book]
    let sections: [Section]
    let passages: [Passage]
    let themes: [Theme]?

    static func decode(from data: Data) throws(AppError) -> SampleLibraryDTO {
        let dto: SampleLibraryDTO
        do {
            dto = try JSONDecoder().decode(SampleLibraryDTO.self, from: data)
        } catch {
            throw .contentCorrupted("sample_library.json: \(error)")
        }
        guard supportedSchemaVersions.contains(dto.schemaVersion) else {
            throw .contentCorrupted("Unsupported schema version \(dto.schemaVersion)")
        }
        return dto
    }
}
